    const button=(txt,fn)=>{const b=document.createElement('button');b.type='button';b.className='btn btn-ghost';b.textContent=txt;b.addEventListener('click',fn);controls.append(b);return b;};
    const play=button('▶ Смотреть',()=>{if(playing)stop();else start();});
    button('↺ Повторить',()=>{time=0;draw();if(!reduced.matches)start();});
    const prev=button('← Шаг',()=>{stop();time=Math.max(0,(Math.ceil(time/stepSeconds)-1)*stepSeconds);draw();});
    const next=button('Шаг →',()=>{stop();time=Math.min(duration,(Math.floor(time/stepSeconds)+1)*stepSeconds);draw();});
